Translate("ruRU", "remains-of-a-paladin", {
	title = "Останки паладина",
	subtitle = "Паладин, убитый в Ульдамане",
	found = "Огромный храмовый зал у входа в Ульдаман",
	hint = "Ищите останки рыцаря-человека в залах Ульдамана.",
	allegiance = "Неизвестно",
	aliases = { "павший паладин Ульдамана" },
	sections = {
		{
			title = "Обзор",
			text = [=[В одном из коридоров {link:ogres}огр{/link}омного храмового зала {link:uldaman}Ульдаман{/link}а лежат останки паладина-человека. Он пришел в {link:badlands}Бесплодные земли{/link} по собственному почину, чтобы изгнать злую скверну, которая, как он верил, лежала на раскопках. Он носил прекрасное магическое ожерелье, которое сделал для него Талваш дель Киссель, {link:gnomes}гном{/link}-ювелир из {link:ironforge}Стальгорн{/link}а. Он погиб в хранилище, его ожерелье было разбито, а самоцветы рассеяны. Рядом с ним лежит его запятнанный кровью дневник, написанный на языке людей.]=],
		},
		{
			title = "Значение",
			text = [=[Смерть паладина отбросила длинную тень. Соперник ювелира распустил слух, будто ожерелье прокляло своего владельца, и ремесло, которым жил Талваш, было погублено. В Орде об ожерелье прослышали собиратели ценностей из компании «Дрофферс и сын» и тоже захотели его получить.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Ни одна запись не называет ни имени паладина, ни его ордена, ни его дома. Что это была за злая скверна и нашел ли он ее, неизвестно.]=],
		},
	},
	chapters = {
		{
			title = "Дневник паладина",
			hint = "Ищите погибшего паладина в залах Ульдамана.",
			text = [=[Дневник был последним трудом паладина. Он выяснил, куда делся каждый самоцвет. {link:dwarves}Дворфы{/link} клана Тенегорн спрятали рубин в своих баррикадах, пока бились с {link:troggs}трогг{/link}ами за хранилище. Трогги положили топаз в урну возле лагеря дворфов {link:ironforge}Стальгорн{/link}а. Вождь троггов забрал сапфир. На стороне Орды дневник не могли прочесть, пока его не перевел тролль {link:jarkal-mossmeld}Джаркал Мохоплав{/link} из {link:kargath}Каргат{/link}а — в обмен на возможность самому изучить ожерелье.]=],
		},
	},
	mentions = {
		{ text = "Разбитое ожерелье" },
		{ text = "Знания за плату" },
		{ text = "Возвращение ожерелья" },
		{ text = "Восстановление ожерелья" },
	},
	bonds = {
